sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var refreshTime = '';

    var ga = new GlideAjax('HSBCTradeTaskUtils');
    ga.addParam('sysparm_name', 'getRefTime');
    ga.getXML(callback);


    function callback(response) {
        refreshTime = response.responseXML.documentElement.getAttribute("answer");
        //Check if an active Task record before refreshing

        var refreshFrequency = g_form.getValue('position_data_refresh_frequency_in_seconds');

        if (refreshFrequency) {
            var submission = confirm('The last refresh of holdings data happened more than ' + parseInt(refreshTime) + ' minutes ago. Do you want to refresh?');

            // Click OK - Position data refresh Frequency in seconds field set to Empty && Event triggered

            if (submission == true) {
                g_form.setValue('position_data_refresh_frequency_in_seconds', '');
                var positionattributeSync = g_form.getValue('position_attribute_sync');

                var gajax = new GlideAjax("x_hsb11_mss_c_proc.getSwiftPosDataUIAction");
                gajax.addParam("sysparm_name", "PositionDataForTask");
                gajax.addParam("sysparm_id", g_form.getUniqueValue());
                gajax.addParam("sysparm_attribute_sync", positionattributeSync);
                gajax.getXMLAnswer(openList);
                g_form.save();
            }
        } else
            return;

    }


    function openList(url) {
        if (url == "Attribute Sync is in progress") {
            g_form.addInfoMessage("Attribute Sync is already in progress");
        }
    }
}
